WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.enUS = WordHunterWoW_QuestDataByFlavor.classic.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[1062] = { title = "Goblin Invaders", description = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!\n\nHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work -- show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...\n\nViolence.", objectives = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1063] = { title = "The Elder Crone", description = "To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.", objectives = "Speak with Magatha in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1064] = { title = "Forsaken Aid", description = "The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.\n\nIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.\n\nSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.", objectives = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1065] = { title = "Journey to Tarren Mill", description = "To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.\n\nA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.\n\nTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.\n\nSeek Lydon and bring him this note.  It details our needs to him.", objectives = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1066] = { title = "Blood of Innocents", description = "I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?\n\nBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.\n\nFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.\n\nYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.", objectives = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1067] = { title = "Return to Thunder Bluff", description = "Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!\n\nBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.", objectives = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1068] = { title = "Shredding Machines", description = "There is a relation to the spiritual magic of shamans and the natural magic of druids.  This is why we shamans can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...\n\nI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!\n\nIn my vision, the machines were marked with strange symbols:\n\nXT:4 and XT:9.", objectives = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1069] = { title = "Deepmoss Spider Eggs", description = "Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.\n\nI smell an opportunity!\n\nIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!\n\nIn Windshear Crag, the eggs will be clustered under what trees remain.\n\nIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...", objectives = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1070] = { title = "On Guard in Stonetalon", description = "Hello, $N.\n\nYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.\n\nRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.\n\nWould you find her and report back to me?", objectives = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1071] = { title = "A Gnome's Respite", description = "You see, $N, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.\n\nBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!\n\nI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...", objectives = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1072] = { title = "An Old Colleague", description = "The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.\n\nAnd for that, we're going to need some potent explosives: Nitromirglyceronium.\n\nThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.\n\nYou talk him into making us some NG-5, I'll get to work on placement for my devices.", objectives = "Speak to Lomac Gearstrip in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1073] = { title = "Ineptitude + Chemicals = Fun", description = "Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!\n\nI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.\n\nThere's a problem though: I'm all out.\n\nBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.\n\nThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.", objectives = "Bring 4 Minor Mana Potions and 2 Elixirs of Fortitude to Lomac Gearstrip in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1074] = { title = "Ineptitude + Chemicals = Fun", description = "Here you go, stranger. Take heed with it though... it's volatile stuff.\n\nIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.", objectives = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1075] = { title = "A Scroll from Mauren", description = "Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?\n\nOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.\n\nBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.", objectives = "Find Collin Mauren in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1076] = { title = "Devils in Westfall", description = "Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.\n\nI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.\n\nWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.\n\nI'll be here when you return.", objectives = "Bring Dust Devil Debris to Collin Mauren in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1077] = { title = "Special Delivery for Gaxim", description = "Here you are, $N. This should do nicely.\n\nPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.\n\nFare well.", objectives = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1078] = { title = "Retrieval for Mauren", description = "Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.\n\nWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.\n\nIf those basilisks still live, I would love to have a few of their scales.\n\nTake your time, it is no rush, but I can pay well.", objectives = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1079] = { title = "Covert Ops - Alpha", description = "This is it, $N. Pay close attention. The devices are done, and ready to be used.\n\nTake these pages--they'll explain more about the detonators and explosives, and where you should place them.\n\nRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.", objectives = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1080] = { title = "Covert Ops - Beta", description = "Plan Beta's just like Plan Alpha, $N.\n\nWe cause a distraction and then steal their precious letters.\n\nThe key is to get their letters... remember that.\n\nThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....", objectives = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1081] = { title = "Reception from Tyrande", description = "$N, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.", objectives = "Find Tyrande Whisperwind in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1082] = { title = "Update for Sentinel Thenysil", description = "$N, you have done a great deed by lending a hand here.\n\nThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.\n\nFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.", objectives = "Return to Sentinel Thenysil in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1083] = { title = "Enraged Spirits", description = "I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.\n\nThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.\n\nBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.\n\nThe land has no chance to see Elune's smile while these creatures roam free.\n\nBring me their smoldering embers to show you've reduced their numbers.", objectives = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1084] = { title = "Wounded Ancients", description = "It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.\n\nGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.\n\nI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.\n\nBring me some of the shrapnel so the gnome can tell me more...", objectives = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1085] = { title = "On Guard in Stonetalon", description = "The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.\n\nThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.\n\nDo not judge Gaxim prematurely; he understands the need for us to work together.\n\nIf you wish to aid us, then start by speaking to Gaxim.\n\nI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.", objectives = "Speak to Gaxim.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1086] = { title = "The Flying Machine Airport", description = "The toxin is ready.  All that remains is its delivery.  You, $N, must make that delivery.\n\nThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.\n\nPlace it, and run.", objectives = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1087] = { title = "Cenarius' Legacy", description = "You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.\n\nWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.\n\nI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.", objectives = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1088] = { title = "Ordanus", description = "They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!\n\nMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.\n\nBring it to me and I will share with you a mighty gift.", objectives = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1089] = { title = "The Den", description = "The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.\n\nThey devised a complex scheme to keep them from falling into the wrong hands.\n\nLuckily, I managed to... extract some details from one of them.\n\nHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.", objectives = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1090] = { title = "Gerenzo's Orders", description = "You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.\n\nAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.", objectives = "Get the mysterious ore from Piznik after he finishes mining it.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1091] = { title = "Kaela's Update", description = "$N, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.\n\nMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.", objectives = "Bring the Venture Co. Letters to Kaela Shadowspear.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1092] = { title = "Gerenzo's Orders", description = "I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.\n\nI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!\n\nI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.", objectives = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1093] = { title = "Super Reaper 6000", description = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!\n\nLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!\n\nTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.", objectives = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1094] = { title = "Further Instructions", description = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.", objectives = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1095] = { title = "Further Instructions", description = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.", objectives = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1096] = { title = "Gerenzo Wrenchwhistle", description = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your while!", objectives = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1097] = { title = "Elmore's Task", description = "There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.\n\nYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.\n\nYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.", objectives = "Speak with Grimand Elmore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1098] = { title = "Deathstalkers in Shadowfang", description = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, $N.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, $N.  Do not fail.", objectives = "Find the Deathstalker Adamant and Deathstalker Vincent.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1100] = { title = "Lonebrow's Journal", description = "You slowly open the weathered journal of Henrig Lonebrow....", objectives = "Read Henrig Lonebrow's Journal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1101] = { title = "The Crone of the Kraul", description = "Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.\n\nWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.\n\nSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. $n, assemble a party to slay the crone.\n\nBring me Razorflank's Medallion as proof of demise.", objectives = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1102] = { title = "A Vengeful Fate", description = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, $n.", objectives = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1103] = { title = "Call of Water", description = "Greetin's, $g brotha:sista;! Have you too come to purify the waters here and prove your understandin' to Islen?\n\nI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.\n\nWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.\n\nBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.", objectives = "Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1104] = { title = "Salt Flat Venom", description = "I have so many designs for our rocket car!  So many!  And I must try them all!!\n\nI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...\n\nThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!\n\nBring me venom and trust me -- our car will fly!!", objectives = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1105] = { title = "Hardened Shells", description = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!\n\nI want to reinforce its fuel tanks before that happens.\n\nThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.\n\nYou look responsible enough.  Will you get me those shells?", objectives = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1106] = { title = "Martek the Exiled", description = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!\n\nBut there is someone who might know how.\n\nHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!\n\nBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!\n\nFind him!", objectives = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1107] = { title = "Encrusted Tail Fins", description = "Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart!\n\nTo prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away.\n\nHave you heard of the Vile Reef, $N?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.", objectives = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1108] = { title = "Indurium", description = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, $N, if you have the guts to get it.\n\nThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.\n\nBut let's make sure.  Get me samples of indurium and I'll test its properties.\n\nTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes.", objectives = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1109] = { title = "Going, Going, Guano!", description = "As you can see, $n, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a $c. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...", objectives = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1110] = { title = "Rocket Car Parts", description = "Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts.  Bring me a heap and I'll pay you well.", objectives = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1111] = { title = "Wharfmaster Dizzywig", description = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.\n\nSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.\n\nDo this for me, and I'll have more jobs for you.\n\nJobs, my friend, with serious profit potential...", objectives = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1112] = { title = "Parts for Kravel", description = "Here's Kravel's package, $N.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!", objectives = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1113] = { title = "Hearts of Zeal", description = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.\n\nIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate. Slay them and bring me their zealous hearts.\n\nOur concoction will be most wicked!", objectives = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1114] = { title = "Delivery to the Gnomes", description = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...\n\nAnd I wouldn't bother mentioning it to him.  It was small and worthless.\n\nTrust me.", objectives = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1115] = { title = "The Rumormonger", description = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  \n\nI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.\n\nIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.\n\nIf you can get useful information from him, then we might just turn a profit from it.", objectives = "Talk to Krazek in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1116] = { title = "Dream Dust in the Swamp", description = "Getting the information on Nazz is quite a favor, $N.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?\n\nWhile I contact my sources, why don't you gather something for me, eh?\n\nHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!\n\nGet it for me, $N, and I'll give you the information you seek.", objectives = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1117] = { title = "Rumors for Kravel", description = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.\n\nHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.\n\nJust don't tell anyone where you got it!", objectives = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1118] = { title = "Back to Booty Bay", description = "$N, you're a $c I can trust, both to get the job done and to keep your mouth shut while doing it.\n\nI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.\n\nTo start, you must go back to Booty Bay.  I apologize, good $N.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.\n\nGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort.", objectives = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1119] = { title = "Zanzil's Mixture and a Fool's Stout", description = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.\n\nAnd $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.", objectives = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1120] = { title = "Get the Gnomes Drunk", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", objectives = "Bring the Fool's Stout to the Gnome Pit Boss.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1121] = { title = "Get the Goblins Drunk", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", objectives = "Bring the Fool's Stout to the Goblin Pit Boss.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1122] = { title = "Report Back to Fizzlebub", description = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!\n\nThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.\n\nAnd hopefully we can get more of that Fool's Stout for future races!", objectives = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1123] = { title = "Rabine Saturna", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.\n\nI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, $N.  Good luck.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1124] = { title = "Wasteland", description = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.\n\nSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.", objectives = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1125] = { title = "The Spirits of Southwind", description = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, $N.\n\nFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...\n\nThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.", objectives = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1126] = { title = "Hive in the Tower", description = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.\n\nThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.", objectives = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity.  Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1127] = { title = "Fool's Stout", description = "So you want some Fool's Stout, eh?  Thinking of heading back to the races...?\n\nAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.", objectives = "Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1130] = { title = "Melor Sends Word", description = "$N, Melor Stonehoof has heard of your deeds, and has set a path before you.\n\nIf you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.", objectives = "Speak with Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1131] = { title = "Steelsnap", description = "At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.\n\nBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.\n\nThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.\n\nFind Steelsnap, $N.  Find him, and defeat him.", objectives = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1132] = { title = "Fiora Longears", description = "Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good $c, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Theramore.  Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!", objectives = "Speak with Fiora Longears in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1133] = { title = "Journey to Astranaar", description = "If you're fresh off the boat from Menethil, then the first thing you should do is... go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.\n\nBut don't bother mentioning who sent you.  Shindrell does not know me...", objectives = "Speak with Shindrell Swiftfire in Astranaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1134] = { title = "Pridewings of Stonetalon", description = "We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly.\n\nOne such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance!\n\nIf this is true, then we must stop them, $N.  We must deny them their source of venom.", objectives = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1135] = { title = "Highperch Venom", description = "As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you.\n\nThere is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.", objectives = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1136] = { title = "Frostmaw", description = "$N, it is now time for you to travel to far-off lands.  You are ready.\n\nYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.\n\nBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.\n\nNow go, $N.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.", objectives = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1137] = { title = "News for Fizzle", description = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.\n\nTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.\n\nSend Fizzle Brassbolts my regards, and tell him what I told you.\n\nSafe travels, $N.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!", objectives = "Speak with Fizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1138] = { title = "Fruit of the Sea", description = "I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it.\n\nI'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...", objectives = "Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1139] = { title = "The Lost Tablets of Will", description = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.\n\nWe must still recover the Tablet before the Shadowforge clan finds it.\n\nReturn to Uldaman, find the tablet, and return here immediately.", objectives = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1140] = { title = "The Tower of Althalaxx", description = "The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.\n\nFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.\n\nBe careful out there, $n, the satyrs' blood-soaked temples can be unsettling even for a seasoned $c such as yourself.", objectives = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1141] = { title = "The Family and the Fishing Pole", description = "I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.\n\nThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.\n\nSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.", objectives = "Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1142] = { title = "Mortality Wanes", description = "I have not long to live... so... so... weak.\n\n...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...\n\nBut before I... d-d-die...\n\n...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...\n\nFind it p-p-please... and return it to Treshala in Darnassus...\n\n...along with w-w-word of my lonely... death.", objectives = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1143] = { title = "The Tower of Althalaxx", description = "I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.", objectives = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1144] = { title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Redleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", objectives = "Escort Willix the Importer out of Razorfen Kraul.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1145] = { title = "The Swarm Grows", description = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\n\nI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.\n\nBelgrom usually be found outside the warriors' guild house.", objectives = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1146] = { title = "The Swarm Grows", description = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.\n\nA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.\n\nThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.", objectives = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1147] = { title = "The Swarm Grows", description = "Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.\n\nI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?", objectives = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1148] = { title = "Parts of the Swarm", description = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.\n\nLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.", objectives = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1149] = { title = "Test of Faith", description = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.", objectives = "If you have faith, leap from the planks overlooking Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1150] = { title = "Test of Endurance", description = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.\n\nFirst is  a test of endurance. Go with friends to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.", objectives = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1151] = { title = "Test of Strength", description = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.\n\nThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.\n\nTo test your strength, find Rok'Alim in Thousand Needles and slay him.", objectives = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1152] = { title = "Test of Lore", description = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, $N.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, $N, the night elves may wish to impede your test.", objectives = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1153] = { title = "A New Ore Sample", description = "$C, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.\n\nTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.", objectives = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1154] = { title = "Test of Lore", description = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.\n\nI shall explain it simply: find the book I name, study it, and answer my question about its contents.\n\nWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.", objectives = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1159] = { title = "Test of Lore", description = "Well done, $N. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.\n\nSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.\n\nHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.", objectives = "Find Parqual Fintallas in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1160] = { title = "Test of Lore", description = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.\n\nGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.\n\nBring it to me.", objectives = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1164] = { title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", objectives = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1166] = { title = "Overlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny $r, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", objectives = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1167] = { title = "The Tower of Althalaxx", description = "Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.", objectives = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1168] = { title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", objectives = "Tharg in Brackenwall Village wants you to kill 15 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Guards.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1169] = { title = "Identifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, $n? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", objectives = "Draz'Zilb in Brackenwall Village would like you to bring him 15 Searing Tongues and 15 Searing Hearts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1170] = { title = "The Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", objectives = "Speak with Overlord Mok'Morokk in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1171] = { title = "The Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", objectives = "Speak with Draz'Zilb in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1172] = { title = "The Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", objectives = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1173] = { title = "Challenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny $r!\n\nYou tell me when ready for good beating.", objectives = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1175] = { title = "A Bump in the Road", description = "After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on.\n\nTell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.", objectives = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1176] = { title = "Load Lightening", description = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.\n\nWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.\n\nBring me some and I'll give you a good price on them.", objectives = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1177] = { title = "Hungry!", description = "Mud big ogre.\n\nMe hungry.\n\nGo bash fishy. Bring Mud food.\n\nYou feed Mud or Mud eat you.", objectives = "Mudcrush Durtfeet in northern Dustwallow wants 12 Mirefin Heads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1178] = { title = "Goblin Sponsorship", description = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.\n\nYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!\n\nA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!", objectives = "Speak to Gazlowe in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1179] = { title = "The Brassbolts Brothers", description = "You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!\n\nA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.\n\nSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!\n\nCan you?", objectives = "Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1180] = { title = "Goblin Sponsorship", description = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.\n\nIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.\n\nCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records.", objectives = "Speak with Wharfmaster Lozgil in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1181] = { title = "Goblin Sponsorship", description = "I'm afraid I can't be of much more help to you, $n. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.\n\nYou'll find him at the tavern across the harbor, top floor.", objectives = "Speak with Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1182] = { title = "Goblin Sponsorship", description = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.\n\nYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.", objectives = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1183] = { title = "Goblin Sponsorship", description = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!", objectives = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1184] = { title = "Parts of the Swarm", description = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.", objectives = "Return to Belgrom Rockmaul in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1185] = { title = "Under the Chitin Was...", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1186] = { title = "The Eighteenth Pilot", description = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.\n\nHe's a little off his rocker, though, so try not to act too surprised.", objectives = "Speak with Razzeric on the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1187] = { title = "Razzeric's Tweaking", description = "Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.\n\nAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!\n\nI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, $n!", objectives = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1188] = { title = "Safety First", description = "But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.\n\nYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.", objectives = "Bring the Seaforium Booster to Shreev in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1189] = { title = "Safety First", description = "There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.\n\nWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?", objectives = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1190] = { title = "Keeping Pace", description = "The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.\n\nWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.\n\nZamek can create a diversion for you, so that you can steal those plans from them.", objectives = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1191] = { title = "Zamek's Distraction", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1192] = { title = "Indurium Ore", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1193] = { title = "A Broken Trap", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1194] = { title = "Rizzle's Schematics", description = "Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.\n\nMuch of the other notes relate to the heat resistant properties.\n\nUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.", objectives = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1195] = { title = "The Sacred Flame", description = "The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.\n\nWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\n\nTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.", objectives = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1196] = { title = "The Sacred Flame", description = "Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.\n\nI wouldn't be surprised if you can help us out further.", objectives = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1197] = { title = "The Sacred Flame", description = "Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.\n\nYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.\n\nBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.", objectives = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1198] = { title = "In Search of Thaelrid", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.\n\nMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out and aid Thaelrid for me, $n.", objectives = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1199] = { title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", objectives = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1200] = { title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Selgorm in Darnassus, $N, please.", objectives = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1201] = { title = "Theramore Spies", description = "The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!\n\nNow is the chance to do just that.\n\nAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.\n\nHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!", objectives = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1202] = { title = "The Theramore Docks", description = "$N, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.\n\nOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.\n\nThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, $N, and bring them to me.", objectives = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1203] = { title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a moonsteel broadsword.  I call it a swing blade.\n\nYou help me?  Maybe you find it in town, maybe you talk to a blacksmith and he'll make it special.\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", objectives = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1204] = { title = "Mudrock Soup and Bugs", description = "I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!\n\nSo, $N, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.\n\nBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...\n\nThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...", objectives = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1205] = { title = "Deadmire", description = "Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.\n\nOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.\n\nYet now he lives in constant, maddening pain.  You must end the life of this noble creature, $N.  You must lead Deadmire to peace.", objectives = "Bring Deadmire's Tooth to Melor in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1206] = { title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", objectives = "Bring 40 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1218] = { title = "Soothing Spices", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd for cooking, I need spice.  Soothing spice.  Then I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", objectives = "Bring 3 Soothing Spices to \"Swamp Eye\" Jarl in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1219] = { title = "The Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", objectives = "Bring the Spy's Report to a Theramore Lieutenant.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1220] = { title = "Captain Vimes", description = "Captain Vimes should see the orc report you found, $N.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", objectives = "Bring the Spy's Report to Captain Garran Vimes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1221] = { title = "Blueleaf Tubers", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.", objectives = "Grab a Crate with Holes.\nGrab a Snufflenose Command Stick.\nGrab and read the Snufflenose Owner's Manual.\n\nIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1222] = { title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!\n\nI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.\n\nThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.\n\nAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?", objectives = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1238] = { title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", objectives = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1239] = { title = "The Severed Head", description = "Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.", objectives = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1240] = { title = "The Troll Witchdoctor", description = "We must know the events surrounding Marg's death!  And the only way to do that, $N, is through the witch-magic of trolls.\n\nBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.\n\nKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.", objectives = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1241] = { title = "The Missing Diplomat", description = "Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.\n\nI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.\n\nAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.\n\nIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.", objectives = "Find Jorgen in Stormwind City.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1242] = { title = "The Missing Diplomat", description = "Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.\n\nI'm gonna only impress this on ya once more, $N: treat this matter seriously, and keep your yapper shut.\n\nYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.", objectives = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1243] = { title = "The Missing Diplomat", description = "Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?\n\nAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!\n\nHere's what's gonna happen, $N. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.\n\nHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.", objectives = "Give the Sealed Note to Watcher Backus in Duskwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1244] = { title = "The Missing Diplomat", description = "Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.\n\nBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.\n\nWhy don't you check there first and bring me back anything you find?\n\nThe farmstead is south of the road from Westfall just as you enter Duskwood.", objectives = "Find the Defias Docket and return it to Watcher Backus in Duskwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1245] = { title = "The Missing Diplomat", description = "Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.\n\nAnd do me a favor, $N, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.", objectives = "Bring the Defias Docket to Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1246] = { title = "The Missing Diplomat", description = "Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.\n\nYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly.", objectives = "Speak to Dashel Stonefist in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1247] = { title = "The Missing Diplomat", description = "So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.\n\nThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.", objectives = "Speak to Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1248] = { title = "The Missing Diplomat", description = "A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.\n\nSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured.", objectives = "Speak to Mikhail in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1249] = { title = "The Missing Diplomat", description = "You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.\n\nHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.\n\nDon't look now, $N, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.", objectives = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1250] = { title = "The Missing Diplomat", description = "The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.\n\nMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!", objectives = "Speak to Mikhail in the Wetlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1251] = { title = "The Black Shield ", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", objectives = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1252] = { title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", objectives = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1253] = { title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", objectives = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1258] = { title = "... and Bugs", description = "Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- Muckshells they call them -- just won't do!  I'm afraid the only suitable crabs live far away, in the Swamp of Sorrows.\n\nThe shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish.\n\nSo, $N... are you willing to travel?", objectives = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1259] = { title = "Lieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", objectives = "Find out more about Reethe from Adjutant Tesoran in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1260] = { title = "Morgan Stern", description = "I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a \"bayou\" theme.  I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long.  Too long for me.  But I bet a young $c like yourself would jump at the chance to travel, yes?", objectives = "Speak with Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1261] = { title = "Marg Speaks", description = "Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...\n\nBut my mission!  My mission!  You, $N, must complete it.\n\nWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!\n\nThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!\n\n$N, you must find that muckshell and recover the pendant!", objectives = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1262] = { title = "Report to Zor", description = "It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!\n\nRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.\n\nTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.", objectives = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1264] = { title = "The Missing Diplomat", description = "The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.\n\nCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discretely.", objectives = "Find Commander Samaul in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1265] = { title = "The Missing Diplomat", description = "Hendel? Yes, I know the man. But why would you need one of my soldiers?\n\nElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.\n\nI believe Hendel was stationed at the first tower outside of Theramore. Be cautious.", objectives = "Search Sentry Point for any sign of Private Hendel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1266] = { title = "The Missing Diplomat", description = "Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.\n\nYou should have no problem finding him; just look for the tents along the road.\n\nI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.", objectives = "Find Private Hendel in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1267] = { title = "The Missing Diplomat", description = "", objectives = "Speak to Jaina Proudmore in Dustwallow Swamp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1268] = { title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1269] = { title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", objectives = "Bring Reethe's Badge to Krog in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1270] = { title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!!\n\nI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.\n\nA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.\n\nToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?", objectives = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1271] = { title = "Feast at the Blue Recluse", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1273] = { title = "Questioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", objectives = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1274] = { title = "The Missing Diplomat", description = "Excuse me, $g sir : madam;. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.\n\nIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.", objectives = "Find Bishop DeLavey in Stormwind Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1275] = { title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga.\n\n'Tis a long journey, $n.", objectives = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1276] = { title = "The Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", objectives = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1282] = { title = "They Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to.", objectives = "Speak with Captain Garran Vimes in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1284] = { title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1285] = { title = "Daelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", objectives = "Return the information about Reethe to Captain Garran Vimes in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1286] = { title = "The Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe deserters' leader is a man named Jacken. See if you can get some information out of him.\n\nBe warned, $n. He may be a tough nut to crack.", objectives = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1287] = { title = "The Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", objectives = "Speak with Captain Garran Vimes in Theramore about Reethe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1301] = { title = "James Hyal", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?", objectives = "Speak with Vincent Hyal in Menethil Harbor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1302] = { title = "James Hyal", description = "My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.\n\nI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him.", objectives = "Speak with Clerk Lendry in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1318] = { title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1319] = { title = "The Black Shield", description = "I'm sorry I can't be of much help, $n, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", objectives = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1320] = { title = "The Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", objectives = "Speak with Captain Garran Vimes in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1321] = { title = "The Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", objectives = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1322] = { title = "The Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the Darkfang spiders in the marsh would do good. Get me some of their sacs and I can clean this up.", objectives = "Acquire 6 Acidic Venom Sacs for Do'gol in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1323] = { title = "The Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", objectives = "Talk with Krog in Brackenwall Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1324] = { title = "The Missing Diplomat", description = "What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.", objectives = "Defeat Private Hendel in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1338] = { title = "Stormpike's Order", description = "There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his!\n\nThe problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there!\n\nSo, if you want to travel and don't mind making some money, then will you send Furen my request for a shield?", objectives = "Bring Stormpike's Request to Furen Longbeard in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1339] = { title = "Mountaineer Stormpike's Task", description = "I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the $r for the job?\n\nIf so, then you'll find Stormpike at the top of the northern guard tower.", objectives = "Speak with Mountaineer Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1358] = { title = "Sample for Helbrim", description = "A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.\n\nHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.", objectives = "Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1359] = { title = "Zinge's Delivery", description = "The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!\n\nIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.", objectives = "Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1360] = { title = "Reclaimed Treasures", description = "I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.\n\nI'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get in.", objectives = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1361] = { title = "Regthar Deathgate", description = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.\n\nAnd sharpen your weapons.  Desolace is a place torn by war.", objectives = "Speak with Regthar Deathgate.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1362] = { title = "The Kolkar of Desolace", description = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.\n\nBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.\n\nSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.", objectives = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1363] = { title = "Mazen's Behest", description = "As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands?\n\nWhich reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?", objectives = "Speak with Acolyte Dellis in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1364] = { title = "Mazen's Behest", description = "Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep.\n\nBut I had never been to the Blasted Lands before! The journey was frightening!\n\nWhen I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure.\n\nCould you please try to retrieve it and deliver it to Mahar Ba?", objectives = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1365] = { title = "Khan Dez'hepah", description = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.\n\nWe must deal with them before they unite.\n\nYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.\n\nThe Kolkar Village is northeast of here.  Go, and may fortune go with you.", objectives = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1366] = { title = "Centaur Bounty", description = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.\n\nBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.\n\nGood hunting, $N.", objectives = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1367] = { title = "Magram Alliance", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.", objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1368] = { title = "Gelkis Alliance", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.", objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1369] = { title = "Broken Tears", description = "The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!\n\nShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!", objectives = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1370] = { title = "Stealing Supplies", description = "When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.\n\nIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.", objectives = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1371] = { title = "Gizmo for Warug", description = "Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.\n\nI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.\n\nI want a new one.  Get me a new one!", objectives = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1372] = { title = "Nothing But The Truth", description = "Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.\n\nWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.\n\nI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.\n\nWork with Faustin here to develop a... truth serum for our friend in Stonard.", objectives = "Speak with Apothecary Faustin at Beggar's Haunt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1373] = { title = "Ongeku", description = "You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.\n\nThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.\n\nBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.", objectives = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1374] = { title = "Khan Jehn", description = "The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!\n\nBring me the head of the Magram Khan, Jehn!", objectives = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1375] = { title = "Khan Shaka", description = "You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!", objectives = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1380] = { title = "Khan Hratha", description = "$N, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!\n\nTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.\n\nBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.\n\nAfter the horn is blown, centaur will come.  Kill them until Hratha appears.\n\nKhan Hratha holds the piece of... a key.  Bring it to me...", objectives = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1381] = { title = "Khan Hratha", description = "The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!\n\nTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.\n\nDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...", objectives = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1382] = { title = "Strange Alliance", description = "We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage.\n\nOne of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis.\n\nSpeak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelkis.", objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1383] = { title = "Nothing But The Truth", description = "I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.\n\nFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, $n, can persuade him to part with some.\n\nNow the hard part will be locating a Deepstrider tumor from far-off Desolace. Very rarely the giants there become ill and a tumor forms.\n\nNow, off you go!", objectives = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and a Deep Strider Tumor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1384] = { title = "Raid on the Kolkar", description = "The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!\n\nYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!", objectives = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1385] = { title = "Brutal Politics", description = "Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow\n\nWe must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance.\n\nEarn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.", objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1386] = { title = "Assault on the Kolkar", description = "The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!", objectives = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1387] = { title = "Centaur Bounty", description = "Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty.\n\nIf we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that.\n\nWhile wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears.\n\nDo this in service of the Alliance, $N, and we will be one step closer to war's end.", objectives = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1388] = { title = "Nothing But The Truth", description = "Everything is proceeding according to plan, $n. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.\n\nHaha!", objectives = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1389] = { title = "Draenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", objectives = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1391] = { title = "Nothing But The Truth", description = "We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?\n\nBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.\n\nMake haste to Stonard in the Swamp of Sorrows, $n. And keep our little mission nice and quiet...", objectives = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1392] = { title = "Noboru the Cudgel", description = "Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.", objectives = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1393] = { title = "Galen's Escape", description = "Please help!  These creatures are going to eat me!\n\nHelp me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know.\n\nIf you help me escape, then I'll teach it to you.", objectives = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1394] = { title = "Final Passage", description = "You have done well, $N. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.\n\nStay true to the balance you've shown throughout these trials, $N. Dorn will test you again in the future if you do.", objectives = "Speak to Dorn Plainstalker in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1395] = { title = "Supplies for Nethergarde", description = "This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan.\n\nYou must take them, and you must take them quickly.\n\nBring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands.\n\nUse caution, $N.  You will travel through dangerous lands, yet you must not fail.", objectives = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1396] = { title = "Encroaching Wildlife", description = "My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies.\n\nI alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!", objectives = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1398] = { title = "Driftwood", description = "I owe you greatly, $N.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid.\n\nIf I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees.\n\n$N, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.", objectives = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1418] = { title = "Neeka Bloodscar", description = "The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, $N.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.", objectives = "Speak with Neeka Bloodscar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1419] = { title = "Coyote Thieves", description = "Have you spent many days in the Badlands, $c?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did.\n\nCrag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves!\n\nHunt crag coyotes, $N.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.", objectives = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1420] = { title = "Report to Helgrum", description = "I wrote a fresh report for Helgrum in Stonard.  Bring it to him.\n\nAnd if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.", objectives = "Bring Neeka's Report to Helgrum the Swift in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1421] = { title = "The Lost Caravan", description = "I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north.\n\nA caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, $N.  Get them and bring them to me.", objectives = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1422] = { title = "Threat From the Sea", description = "While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.", objectives = "Speak to Katar in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1423] = { title = "The Lost Supplies", description = "This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words:\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP", objectives = "Bring the Lost Supplies to Quartermaster Lungertz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1424] = { title = "Pool of Tears", description = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.\n\nThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.\n\nThe green dragons now guard the site, claiming to be protectors of Azeroth.\n\nWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.", objectives = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1425] = { title = "Deliver the Shipment", description = "While I fix this wagon, $N, I have one last task for you.\n\nI have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal.\n\nTo reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, $N, and be wary.", objectives = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1426] = { title = "Threat From the Sea", description = "I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.\n\nWhich brings us to you, $c. How many can you slay? Would you test yourself against their most powerful kind?", objectives = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1427] = { title = "Threat From the Sea", description = "Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.", objectives = "Speak with Tok'Kar in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1428] = { title = "Continued Threat", description = "It pleases me to see your hatred for the fish men grows with mine.\n\nFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.", objectives = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1429] = { title = "The Atal'ai Exile", description = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.\n\nThis priest was sentenced to a fate worse than death amongst the Atal'ai.\n\nHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.\n\nI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.", objectives = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1430] = { title = "Fresh Meat", description = "There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.\n\nIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.\n\nThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.", objectives = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1431] = { title = "Alliance Relations", description = "Be still, $c, and allow me to share with you something important to our people, but far from obvious.\n\nWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.\n\nIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.", objectives = "Speak to Keldran in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1432] = { title = "Alliance Relations", description = "As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.\n\nI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.", objectives = "Speak to Takata Steelblade in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1433] = { title = "Alliance Relations", description = "The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.\n\nKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.\n\nHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.\n\nSpeak to him, and he will guide you in his designs.", objectives = "Speak to Maurin Bonesplitter in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1434] = { title = "Befouled by Satyr", description = "A demon infestation does not occur without other influences--something else allows evil to gain a foothold.\n\nIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.\n\nTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.", objectives = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1435] = { title = "The Burning of Spirits", description = "Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.\n\nTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.\n\nBring me these infused gems so I may dispose of them properly.\n\nGo now, and may you elude death.", objectives = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1436] = { title = "Alliance Relations", description = "The fight goes well, $N. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings.\n\nReturn to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.", objectives = "Speak to Keldran in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1437] = { title = "Vahlarriel's Search", description = "I am Vahlarriel, $N. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.\n\nLast word tells of them passing through the Stonetalon Mountains a few weeks ago.\n\nIf you find their wagon, please, come find me immediately.", objectives = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1438] = { title = "Vahlarriel's Search", description = "Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.\n\n$N, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.", objectives = "Find Dalinda Malem in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1439] = { title = "Search for Tyranis", description = "We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.\n\nTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.\n\nPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.", objectives = "Find Tyranis Malem in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1440] = { title = "Return to Vahlarriel", description = "So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.", objectives = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1442] = { title = "Seeking the Kor Gem", description = "Greetings, $N. What can I do for one who follows a holy path?\n\nAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.\n\nHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.\n\nIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, $c.", objectives = "Bring a Kor Gem to Thundris Windweaver in Darkshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1444] = { title = "Return to Fel'Zerul", description = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....", objectives = "Return to Fel'Zerul in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1445] = { title = "The Temple of Atal'Hakkar", description = "So he spoke of Jammal'an's prophecy?\n\nThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.\n\nFoolish trickery to bring about a premature doomsday if you ask me.\n\nBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.\n\nVenture into the Temple, and seize the fetishes!", objectives = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1446] = { title = "Jammal'an the Prophet", description = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.", objectives = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1447] = { title = "The Missing Diplomat", description = " Yeah, you're obviously not the smartest $c to come into Stormwind, but you're about to be one of the dumbest to never leave.\n\nHave you met me friends?", objectives = "Defeat Dashel Stonefist in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
